// Formata el pedido que llega de la API de Vercel (POST /api/orders)
const items = ($json.body?.items || [])
  .map((i) => `${i.quantity} x ${i.product?.name} = $${Number(i.product?.price * i.quantity).toFixed(2)}`)
  .join('\n');

const body = $json.body || {};

return [
  {
    json: {
      eventId: body.event || 'pedido.nuevo',
      orderId: body.orderId || 'SIN-ID',
      nombre: body.customerName || '',
      telefono: body.customerPhone || '',
      modalidad: body.deliveryType === 'pickup' ? 'Retirar en tienda' : 'Delivery',
      direccion: body.deliveryAddress || '',
      horario: body.deliverySlot || '',
      pago: body.paymentMethod || '',
      subtotal: body.subtotal ?? 0,
      envio: body.deliveryFee ?? 0,
      propina: body.tip ?? 0,
      total: body.total ?? 0,
      creado: body.createdAt || new Date().toISOString(),
      productos: items,
      resumen: `🛍️ Pedido ${body.orderId}\n👤 ${body.customerName}\n📞 ${body.customerPhone}\n📍 ${body.deliveryAddress || 'Retiro en tienda'}\n\n${items}\n\n💰 Total: $${Number(body.total || 0).toFixed(2)}`
    }
  }
];
